-- 悬空与口径检查（生成物）：灌库后、VALIDATE 前跑，每条应返回 0 行。
SELECT 'book.work_id 悬空' chk, r.id, r.work_id FROM book r WHERE r.work_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM work x WHERE x.id = r.work_id);
SELECT 'collection.work_id 悬空' chk, r.id, r.work_id FROM collection r WHERE r.work_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM work x WHERE x.id = r.work_id);
SELECT 'authorship.entity_id 悬空' chk, r.owner_id, r.entity_id FROM authorship r WHERE r.entity_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM entity x WHERE x.id = r.entity_id);
SELECT 'member_of.collection_id 悬空' chk, r.member_id, r.collection_id FROM member_of r WHERE r.collection_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM collection x WHERE x.id = r.collection_id);
SELECT 'index_entry.source_bid 悬空' chk, r.owner_id, r.source_bid FROM index_entry r WHERE r.source_bid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM work x WHERE x.id = r.source_bid);
SELECT 'book_seal_mark.seal_id 悬空' chk, r.owner_id, r.seal_id FROM book_seal_mark r WHERE r.seal_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM entity x WHERE x.id = r.seal_id);
SELECT 'book_base_edition.book_id 悬空' chk, r.owner_id, r.book_id FROM book_base_edition r WHERE r.book_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM book x WHERE x.id = r.book_id);
SELECT 'person.native_place_entity_id 悬空' chk, r.id, r.native_place_entity_id FROM person r WHERE r.native_place_entity_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM entity x WHERE x.id = r.native_place_entity_id);
SELECT 'office.base_office_id 悬空' chk, r.id, r.base_office_id FROM office r WHERE r.base_office_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM entity x WHERE x.id = r.base_office_id);
SELECT 'place_history_dynasty.dynasty_id 悬空' chk, r.owner_id, r.dynasty_id FROM place_history_dynasty r WHERE r.dynasty_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM entity x WHERE x.id = r.dynasty_id);
SELECT 'entity_relation.dst 悬空' chk, r.src, r.dst FROM entity_relation r WHERE r.dst IS NOT NULL AND NOT EXISTS (SELECT 1 FROM entity x WHERE x.id = r.dst);
SELECT 'work_relation.dst 悬空' chk, r.src, r.dst FROM work_relation r WHERE r.dst IS NOT NULL AND NOT EXISTS (SELECT 1 FROM work x WHERE x.id = r.dst) AND NOT EXISTS (SELECT 1 FROM collection x WHERE x.id = r.dst);
SELECT 'related_record.dst 悬空' chk, r.src, r.dst FROM related_record r WHERE r.dst IS NOT NULL AND NOT EXISTS (SELECT 1 FROM book x WHERE x.id = r.dst) AND NOT EXISTS (SELECT 1 FROM collection x WHERE x.id = r.dst);
SELECT 'id_map.live_id 悬空' chk, r.old_id, r.live_id FROM id_map r WHERE r.live_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM work x WHERE x.id = r.live_id) AND NOT EXISTS (SELECT 1 FROM book x WHERE x.id = r.live_id) AND NOT EXISTS (SELECT 1 FROM collection x WHERE x.id = r.live_id) AND NOT EXISTS (SELECT 1 FROM entity x WHERE x.id = r.live_id);
-- 旧号要解得到现行记录，终点不能还是墓碑
SELECT 'id_map.live_id 解不到' chk, m.old_id, m.src, m.direct_into FROM id_map m WHERE m.live_id IS NULL;
SELECT 'id_map.live_id 仍是墓碑' chk, m.old_id, m.live_id FROM id_map m WHERE m.live_id IN (SELECT old_id FROM id_map WHERE src = 'tombstone');
-- 共用明细表的 owner_type 与 id 实际所在主表一致
SELECT 'authorship.owner_type 不符' chk, r.owner_id FROM authorship r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.owner_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.owner_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.owner_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.owner_id)));
SELECT 'index_entry.owner_type 不符' chk, r.owner_id FROM index_entry r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.owner_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.owner_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.owner_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.owner_id)));
SELECT 'source_ref.owner_type 不符' chk, r.owner_id FROM source_ref r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.owner_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.owner_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.owner_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.owner_id)));
SELECT 'resource.owner_type 不符' chk, r.owner_id FROM resource r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.owner_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.owner_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.owner_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.owner_id)));
SELECT 'resource_group.owner_type 不符' chk, r.owner_id FROM resource_group r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.owner_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.owner_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.owner_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.owner_id)));
SELECT 'member_of.owner_type 不符' chk, r.member_id FROM member_of r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.member_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.member_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.member_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.member_id)));
SELECT 'measure.owner_type 不符' chk, r.owner_id FROM measure r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.owner_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.owner_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.owner_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.owner_id)));
SELECT 'id_map.owner_type 不符' chk, r.live_id FROM id_map r WHERE r.live_id IS NOT NULL AND NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.live_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.live_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.live_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.live_id)));
SELECT 'description_source.owner_type 不符' chk, r.owner_id FROM description_source r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.owner_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.owner_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.owner_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.owner_id)));
SELECT 'alt_name.owner_type 不符' chk, r.owner_id FROM alt_name r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.owner_id)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.owner_id)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.owner_id)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.owner_id)));
SELECT 'related_record.owner_type 不符' chk, r.src FROM related_record r WHERE NOT ((r.owner_type = 'B' AND EXISTS (SELECT 1 FROM book x WHERE x.id = r.src)) OR (r.owner_type = 'C' AND EXISTS (SELECT 1 FROM collection x WHERE x.id = r.src)) OR (r.owner_type = 'E' AND EXISTS (SELECT 1 FROM entity x WHERE x.id = r.src)) OR (r.owner_type = 'W' AND EXISTS (SELECT 1 FROM work x WHERE x.id = r.src)));
-- 四类主表 id 不得重复
SELECT 'id 跨类重复' chk, id FROM (SELECT id FROM work UNION ALL SELECT id FROM book UNION ALL SELECT id FROM collection UNION ALL SELECT id FROM entity) t GROUP BY id HAVING count(*) > 1;
